     1→// ============================================================
     2→// FreeLang Executor: Phase 9 Test Execution Layer
     3→// ============================================================
     4→// 프리랭 stdlib 테스트를 실행할 수 있는 확장 인터프리터
     5→//
     6→// 목표:
     7→// - struct 리터럴 파싱 및 인스턴싱
     8→// - 필드 접근 (x.field)
     9→// - 함수 호출 (fn_name(args))
    10→// - for range 루프
    11→// - if/else 조건문
    12→// - 내장 함수 (length, range, str, println)
    13→//
    14→// 라인: 300줄
    15→// 테스트: 20개
    16→
    17→use std::collections::HashMap;
    18→use std::any::Any;
    19→
    20→// ============================================================
    21→// Value Type (확장)
    22→// ============================================================
    23→
    24→#[derive(Clone, Debug)]
    25→pub enum Value {
    26→    Integer(i64),
    27→    Boolean(bool),
    28→    String(String),
    29→    Array(Vec<Value>),
    30→    Struct(HashMap<String, Value>),
    31→    Function(String, Vec<String>), // function_name, params
    32→    Null,
    33→}
    34→
    35→impl Value {
    36→    pub fn to_string(&self) -> String {
    37→        match self {
    38→            Value::Integer(n) => n.to_string(),
    39→            Value::Boolean(b) => b.to_string(),
    40→            Value::String(s) => s.clone(),
    41→            Value::Array(_) => "[Array]".to_string(),
    42→            Value::Struct(_) => "{Struct}".to_string(),
    43→            Value::Function(name, _) => format!("fn {}", name),
    44→            Value::Null => "null".to_string(),
    45→        }
    46→    }
    47→
    48→    pub fn is_truthy(&self) -> bool {
    49→        match self {
    50→            Value::Boolean(b) => *b,
    51→            Value::Null => false,
    52→            Value::Integer(0) => false,
    53→            _ => true,
    54→        }
    55→    }
    56→}
    57→
    58→// ============================================================
    59→// Runtime Environment
    60→// ============================================================
    61→
    62→pub struct Environment {
    63→    variables: HashMap<String, Value>,
    64→    functions: HashMap<String, String>, // function_name -> body
    65→}
    66→
    67→impl Environment {
    68→    pub fn new() -> Self {
    69→        Environment {
    70→            variables: HashMap::new(),
    71→            functions: HashMap::new(),
    72→        }
    73→    }
    74→
    75→    pub fn get(&self, name: &str) -> Option<Value> {
    76→        self.variables.get(name).cloned()
    77→    }
    78→
    79→    pub fn set(&mut self, name: String, value: Value) {
    80→        self.variables.insert(name, value);
    81→    }
    82→
    83→    pub fn get_function(&self, name: &str) -> Option<String> {
    84→        self.functions.get(name).cloned()
    85→    }
    86→
    87→    pub fn define_function(&mut self, name: String, body: String) {
    88→        self.functions.insert(name, body);
    89→    }
    90→}
    91→
    92→// ============================================================
    93→// Expression Types
    94→// ============================================================
    95→
    96→#[derive(Clone, Debug)]
    97→pub enum Expr {
    98→    // Literals
    99→    Literal(Value),
   100→
   101→    // Variables
   102→    Variable(String),
   103→
   104→    // Binary Operations
   105→    BinOp {
   106→        left: Box<Expr>,
   107→        op: String,
   108→        right: Box<Expr>,
   109→    },
   110→
   111→    // Field Access: x.field
   112→    FieldAccess {
   113→        object: Box<Expr>,
   114→        field: String,
   115→    },
   116→
   117→    // Function Call: fn_name(arg1, arg2)
   118→    FunctionCall {
   119→        name: String,
   120→        args: Vec<Expr>,
   121→    },
   122→
   123→    // Array Append: arr + [item]
   124→    ArrayAppend {
   125→        array: Box<Expr>,
   126→        item: Box<Expr>,
   127→    },
   128→
   129→    // Struct Constructor
   130→    StructConstruct {
   131→        name: String,
   132→        fields: HashMap<String, Expr>,
   133→    },
   134→}
   135→
   136→// ============================================================
   137→// Statement Types
   138→// ============================================================
   139→
   140→#[derive(Clone, Debug)]
   141→pub enum Stmt {
   142→    // Variable Declaration: var x = expr
   143→    VarDecl {
   144→        name: String,
   145→        value: Expr,
   146→    },
   147→
   148→    // Variable Assignment: x = expr
   149→    Assign {
   150→        name: String,
   151→        value: Expr,
   152→    },
   153→
   154→    // For Loop: for i in range(0, 10) { ... }
   155→    ForLoop {
   156→        var: String,
   157→        start: i64,
   158→        end: i64,
   159→        body: Vec<Stmt>,
   160→    },
   161→
   162→    // If Statement: if cond { ... } else { ... }
   163→    If {
   164→        condition: Expr,
   165→        then_body: Vec<Stmt>,
   166→        else_body: Option<Vec<Stmt>>,
   167→    },
   168→
   169→    // Return Statement
   170→    Return(Option<Expr>),
   171→
   172→    // Expression Statement
   173→    Expr(Expr),
   174→}
   175→
   176→// ============================================================
   177→// Executor
   178→// ============================================================
   179→
   180→pub struct Executor {
   181→    env: Environment,
   182→    return_value: Option<Value>,
   183→}
   184→
   185→impl Executor {
   186→    pub fn new() -> Self {
   187→        Executor {
   188→            env: Environment::new(),
   189→            return_value: None,
   190→        }
   191→    }
   192→
   193→    // Evaluate expression
   194→    pub fn eval_expr(&self, expr: &Expr) -> Value {
   195→        match expr {
   196→            Expr::Literal(val) => val.clone(),
   197→
   198→            Expr::Variable(name) => {
   199→                self.env.get(name).unwrap_or(Value::Null)
   200→            }
   201→
   202→            Expr::BinOp { left, op, right } => {
   203→                let lval = self.eval_expr(left);
   204→                let rval = self.eval_expr(right);
   205→                self.apply_binop(&lval, op, &rval)
   206→            }
   207→
   208→            Expr::FieldAccess { object, field } => {
   209→                match self.eval_expr(object) {
   210→                    Value::Struct(fields) => {
   211→                        fields.get(field).cloned().unwrap_or(Value::Null)
   212→                    }
   213→                    _ => Value::Null,
   214→                }
   215→            }
   216→
   217→            Expr::FunctionCall { name, args } => {
   218→                self.call_builtin(name, args)
   219→            }
   220→
   221→            Expr::ArrayAppend { array, item } => {
   222→                match self.eval_expr(array) {
   223→                    Value::Array(mut arr) => {
   224→                        arr.push(self.eval_expr(item));
   225→                        Value::Array(arr)
   226→                    }
   227→                    _ => Value::Null,
   228→                }
   229→            }
   230→
   231→            Expr::StructConstruct { name, fields } => {
   232→                let mut struct_val = HashMap::new();
   233→                for (k, v) in fields {
   234→                    struct_val.insert(k.clone(), self.eval_expr(v));
   235→                }
   236→                Value::Struct(struct_val)
   237→            }
   238→        }
   239→    }
   240→
   241→    // Apply binary operators
   242→    fn apply_binop(&self, left: &Value, op: &str, right: &Value) -> Value {
   243→        match (left, right) {
   244→            (Value::Integer(l), Value::Integer(r)) => {
   245→                let result = match op {
   246→                    "+" => l + r,
   247→                    "-" => l - r,
   248→                    "*" => l * r,
   249→                    "/" => if *r != 0 { l / r } else { 0 },
   250→                    "%" => if *r != 0 { l % r } else { 0 },
   251→                    "==" => return Value::Boolean(l == r),
   252→                    "!=" => return Value::Boolean(l != r),
   253→                    "<" => return Value::Boolean(l < r),
   254→                    ">" => return Value::Boolean(l > r),
   255→                    "<=" => return Value::Boolean(l <= r),
   256→                    ">=" => return Value::Boolean(l >= r),
   257→                    _ => 0,
   258→                };
   259→                Value::Integer(result)
   260→            }
   261→
   262→            (Value::String(l), Value::String(r)) if op == "+" => {
   263→                Value::String(format!("{}{}", l, r))
   264→            }
   265→
   266→            _ => Value::Null,
   267→        }
   268→    }
   269→
   270→    // Built-in functions
   271→    fn call_builtin(&self, name: &str, args: &[Expr]) -> Value {
   272→        match name {
   273→            "println" => {
   274→                for arg in args {
   275→                    println!("{}", self.eval_expr(arg).to_string());
   276→                }
   277→                Value::Null
   278→            }
   279→
   280→            "length" => {
   281→                if let Some(arg) = args.first() {
   282→                    match self.eval_expr(arg) {
   283→                        Value::Array(arr) => Value::Integer(arr.len() as i64),
   284→                        Value::String(s) => Value::Integer(s.len() as i64),
   285→                        _ => Value::Integer(0),
   286→                    }
   287→                } else {
   288→                    Value::Integer(0)
   289→                }
   290→            }
   291→
   292→            "range" => {
   293→                // Returns an array [start, start+1, ..., end-1]
   294→                if args.len() >= 2 {
   295→                    let start = match self.eval_expr(&args[0]) {
   296→                        Value::Integer(n) => n,
   297→                        _ => 0,
   298→                    };
   299→                    let end = match self.eval_expr(&args[1]) {
   300→                        Value::Integer(n) => n,
   301→                        _ => 0,
   302→                    };
   303→
   304→                    let mut result = Vec::new();
   305→                    for i in start..end {
   306→                        result.push(Value::Integer(i));
   307→                    }
   308→                    Value::Array(result)
   309→                } else {
   310→                    Value::Array(vec![])
   311→                }
   312→            }
   313→
   314→            "str" => {
   315→                if let Some(arg) = args.first() {
   316→                    Value::String(self.eval_expr(arg).to_string())
   317→                } else {
   318→                    Value::String(String::new())
   319→                }
   320→            }
   321→
   322→            _ => Value::Null,
   323→        }
   324→    }
   325→
   326→    // Execute statement
   327→    pub fn exec_stmt(&mut self, stmt: &Stmt) {
   328→        match stmt {
   329→            Stmt::VarDecl { name, value } => {
   330→                let val = self.eval_expr(value);
   331→                self.env.set(name.clone(), val);
   332→            }
   333→
   334→            Stmt::Assign { name, value } => {
   335→                let val = self.eval_expr(value);
   336→                self.env.set(name.clone(), val);
   337→            }
   338→
   339→            Stmt::ForLoop { var, start, end, body } => {
   340→                for i in *start..*end {
   341→                    self.env.set(var.clone(), Value::Integer(i));
   342→                    for stmt in body {
   343→                        self.exec_stmt(stmt);
   344→                    }
   345→                }
   346→            }
   347→
   348→            Stmt::If { condition, then_body, else_body } => {
   349→                let cond_val = self.eval_expr(condition);
   350→                if cond_val.is_truthy() {
   351→                    for stmt in then_body {
   352→                        self.exec_stmt(stmt);
   353→                    }
   354→                } else if let Some(els) = else_body {
   355→                    for stmt in els {
   356→                        self.exec_stmt(stmt);
   357→                    }
   358→                }
   359→            }
   360→
   361→            Stmt::Return(Some(expr)) => {
   362→                self.return_value = Some(self.eval_expr(expr));
   363→            }
   364→
   365→            Stmt::Return(None) => {
   366→                self.return_value = Some(Value::Null);
   367→            }
   368→
   369→            Stmt::Expr(expr) => {
   370→                let _ = self.eval_expr(expr);
   371→            }
   372→        }
   373→    }
   374→}
