    11→#[derive(Debug, Clone)]
    12→pub struct CompileResult {
    13→    pub work_id: u64,
    14→    pub success: bool,
    15→    pub error_count: usize,
    16→    pub warnings: Vec<String>,
    17→    pub compile_time_ms: u64,
    18→}
    19→
    20→impl CompileResult {
    21→    pub fn success(work_id: u64, time_ms: u64) -> Self {
