   112→/// Worker: Represents a single compilation worker thread
   113→pub struct Worker {
   114→    id: u32,
   115→    state: Arc<SharedState>,
   116→    queue: WorkQueue,
   117→    active: Arc<AtomicBool>,
   118→}
   119→
   120→impl Worker {
   121→    pub fn new(id: u32, state: Arc<SharedState>, queue: WorkQueue) -> Self {
   122→        Worker {
   123→            id,
   124→            state,
   125→            queue,
   126→            active: Arc::new(AtomicBool::new(true)),
   127→        }
   128→    }
   129→
   130→    /// Tokenize source code into tokens
   131→    fn tokenize(&self, source: &str) -> Vec<Token> {
   132→        let mut tokens = Vec::new();
   133→        let mut token_id = 0u64;
   134→
   135→        // Simple tokenization (split by whitespace and punctuation)
   136→        for (line_idx, line) in source.lines().enumerate() {
   137→            let mut col = 0;
   138→            for word in line.split_whitespace() {
   139→                if let Ok(cache) = self.state.token_cache.lock() {
   140→                    if let Some(cached) = cache.lookup(token_id) {
   141→                        tokens.push(cached);
   142→                        token_id += 1;
   143→                        col += word.len() as u32;
   144→                        continue;
   145→                    }
   146→                }
   147→
   148→                let token_type = match word {
   149→                    "let" | "fn" | "if" | "else" | "for" | "while" => 0, // keyword
   150→                    _ if word.parse::<i64>().is_ok() => 2, // literal
   151→                    _ => 1, // identifier
   152→                };
   153→
   154→                let token = Token::new(
   155→                    token_id,
   156→                    token_type,
   157→                    word.to_string(),
   158→                    (line_idx + 1) as u32,
   159→                    col,
   160→                );
   161→
   162→                tokens.push(token);
   163→                token_id += 1;
   164→                col += word.len() as u32 + 1;
   165→            }
   166→        }
   167→
   168→        tokens
   169→    }
   170→
   171→    /// Parse tokens into AST-like structure (simplified)
   172→    fn parse(&self, tokens: &[Token]) -> Result<(), String> {
   173→        for token in tokens {
   174→            if token.token_type == 0 && token.value == "let" {
   175→                // Simple variable declaration parsing
   176→                if tokens.len() > 2 {
   177→                    let var = Variable {
   178→                        name: format!("var_{}", token.id),
   179→                        var_type: "i32".to_string(),
   180→                        scope: 0,
   181→                        value: None,
   182→                    };
   183→                    self.state.add_variable(var)?;
   184→                }
   185→            } else if token.token_type == 0 && token.value == "fn" {
   186→                // Simple function declaration parsing
   187→                let func = Function {
   188→                    name: format!("func_{}", token.id),
   189→                    params: Vec::new(),
   190→                    return_type: "i32".to_string(),
   191→                    scope: 0,
   192→                };
   193→                self.state.add_function(func)?;
   194→            }
   195→        }
   196→        Ok(())
   197→    }
   198→
   199→    /// Compile a single work item
   200→    pub fn compile(&self, work: WorkItem) -> CompileResult {
   201→        let start = std::time::Instant::now();
   202→
   203→        // Tokenization phase
   204→        let tokens = self.tokenize(&work.source_code);
   205→        let token_count = tokens.len() as u64;
   206→
   207→        // Update cache with new tokens
   208→        if let Ok(mut cache) = self.state.token_cache.lock() {
   209→            for token in &tokens {
   210→                let _ = cache.insert(token.clone());
   211→            }
   212→        }
   213→
   214→        // Parsing phase
   215→        let parse_result = self.parse(&tokens);
   216→
   217→        let elapsed = start.elapsed().as_millis() as u64;
   218→
   219→        // Update metrics
   220→        self.state.update_metrics(token_count, elapsed * 1_000_000); // Convert to ns
   221→
   222→        match parse_result {
   223→            Ok(_) => CompileResult::success(work.id, elapsed),
   224→            Err(e) => {
   225→                self.state.record_error(e.clone());
   226→                CompileResult::failure(work.id, 1, elapsed)
   227→            }
   228→        }
   229→    }
   230→
   231→    /// Worker thread main loop
   232→    pub fn run(&self) {
   233→        while self.active.load(Ordering::Relaxed) {
   234→            match self.queue.dequeue() {
   235→                Some(work) => {
   236→                    let result = self.compile(work);
   237→                    self.queue.add_result(result);
   238→                }
   239→                None => {
   240→                    // Idle
   241→                    thread::sleep(std::time::Duration::from_millis(1));
   242→                }
   243→            }
   244→        }
   245→    }
   246→
   247→    pub fn stop(&self) {
   248→        self.active.store(false, Ordering::Relaxed);
   249→    }
   250→}
