   252→/// ParallelCompiler: Main coordinator for 4 workers
   253→pub struct ParallelCompiler {
   254→    num_workers: u32,
   255→    state: Arc<SharedState>,
   256→    queue: WorkQueue,
   257→}
   258→
   259→impl ParallelCompiler {
   260→    pub fn new() -> Self {
   261→        ParallelCompiler::with_workers(4)
   262→    }
   263→
   264→    pub fn with_workers(num_workers: u32) -> Self {
   265→        let state = Arc::new(SharedState::new(1024)); // 1K token cache
   266→        let queue = WorkQueue::new();
   267→
   268→        ParallelCompiler {
   269→            num_workers,
   270→            state,
   271→            queue,
   272→        }
   273→    }
   274→
   275→    /// Submit work items for compilation
   276→    pub fn submit(&self, items: Vec<WorkItem>) -> Result<(), String> {
   277→        for item in items {
   278→            self.queue.enqueue(item)?;
   279→        }
   280→        Ok(())
   281→    }
   282→
   283→    /// Compile in parallel (blocking)
   284→    pub fn compile_parallel(&self, source_codes: Vec<String>) -> Vec<CompileResult> {
   285→        // Prepare work items
   286→        let mut work_items = Vec::new();
   287→        for (idx, source) in source_codes.iter().enumerate() {
   288→            work_items.push(WorkItem::new(idx as u64, source.clone()));
   289→        }
   290→
   291→        // Submit to queue
   292→        let _ = self.submit(work_items);
   293→
   294→        // Spawn worker threads
   295→        let mut handles = vec![];
   296→        for worker_id in 0..self.num_workers {
   297→            let state = Arc::clone(&self.state);
   298→            let queue = self.queue.clone();
   299→
   300→            let handle = thread::spawn(move || {
   301→                let worker = Worker::new(worker_id, state, queue);
   302→                worker.run();
   303→            });
   304→
   305→            handles.push(handle);
   306→        }
   307→
   308→        // Wait for all work to complete
   309→        while !self.queue.is_empty() {
   310→            thread::sleep(std::time::Duration::from_millis(10));
   311→        }
   312→
   313→        // Collect results
   314→        let results = self.queue.get_results();
   315→
   316→        // Signal workers to stop (they will exit when queue is empty)
   317→        // In production, we'd use proper shutdown signals
   318→        for handle in handles {
   319→            // Don't wait for handles to avoid hanging
   320→            drop(handle);
   321→        }
   322→
   323→        results
   324→    }
   325→
   326→    /// Non-blocking submit with callback
   327→    pub fn submit_async(&self, items: Vec<WorkItem>) -> Result<(), String> {
   328→        self.submit(items)
   329→    }
   330→
   331→    /// Get cache hit rate
   332→    pub fn cache_hit_rate(&self) -> f64 {
   333→        self.state.token_cache_hit_rate()
   334→    }
   335→
   336→    /// Get compilation metrics
   337→    pub fn get_metrics(&self) -> (u64, u64) {
   338→        self.state.get_metrics()
   339→    }
   340→
   341→    /// Get all compilation results
   342→    pub fn get_results(&self) -> Vec<CompileResult> {
   343→        self.queue.get_results()
   344→    }
   345→
   346→    /// Clear internal state
   347→    pub fn clear(&self) {
   348→        self.state.clear();
   349→    }
   350→}
   351→
   352→impl Default for ParallelCompiler {
   353→    fn default() -> Self {
   354→        Self::new()
   355→    }
   356→}
