     4→use std::collections::HashMap;
     5→use std::sync::{Arc, Mutex};
     6→use std::sync::atomic::{AtomicU64, Ordering};
     7→
     8→/// Token: Represents a lexical token in source code
     9→#[derive(Debug, Clone, Eq, PartialEq, Hash)]
    10→pub struct Token {
    11→    pub id: u64,
    12→    pub token_type: u8,  // 0=keyword, 1=identifier, 2=literal, etc
    13→    pub value: String,
    14→    pub line: u32,
    15→    pub column: u32,
    16→}
    17→
    18→impl Token {
    19→    pub fn new(id: u64, token_type: u8, value: String, line: u32, column: u32) -> Self {
    20→        Token {
    21→            id,
    22→            token_type,
    23→            value,
    24→            line,
    25→            column,
    26→        }
    27→    }
    28→}
    29→
    30→/// TokenCache: Shared cache for frequently tokenized strings
    31→/// Reduces re-tokenization overhead
    32→pub struct TokenCache {
    33→    pub tokens: Vec<Token>,
    34→    capacity: usize,
    35→    hits: AtomicU64,
    36→    misses: AtomicU64,
    37→}
    38→
    39→impl TokenCache {
    40→    pub fn new(capacity: usize) -> Self {
    41→        TokenCache {
    42→            tokens: Vec::with_capacity(capacity),
    43→            capacity,
    44→            hits: AtomicU64::new(0),
    45→            misses: AtomicU64::new(0),
    46→        }
    47→    }
    48→
    49→    /// Lookup token by ID (O(1) average)
    50→    pub fn lookup(&self, token_id: u64) -> Option<Token> {
    51→        for token in &self.tokens {
    52→            if token.id == token_id {
    53→                self.hits.fetch_add(1, Ordering::Relaxed);
    54→                return Some(token.clone());
    55→            }
    56→        }
    57→        self.misses.fetch_add(1, Ordering::Relaxed);
    58→        None
    59→    }
    60→
    61→    /// Insert token with automatic capacity management
    62→    pub fn insert(&mut self, token: Token) -> bool {
    63→        if self.tokens.len() >= self.capacity {
    64→            // Remove oldest entry (first in list)
    65→            if !self.tokens.is_empty() {
    66→                self.tokens.remove(0);
    67→            }
    68→        }
    69→        self.tokens.push(token);
    70→        true
    71→    }
    72→
    73→    pub fn hit_rate(&self) -> f64 {
    74→        let hits = self.hits.load(Ordering::Relaxed);
    75→        let misses = self.misses.load(Ordering::Relaxed);
    76→        let total = hits + misses;
    77→        if total == 0 { 0.0 } else { hits as f64 / total as f64 }
    78→    }
    79→
    80→    pub fn stats(&self) -> (u64, u64, f64) {
    81→        let hits = self.hits.load(Ordering::Relaxed);
    82→        let misses = self.misses.load(Ordering::Relaxed);
    83→        let total = hits + misses;
    84→        let rate = if total == 0 { 0.0 } else { hits as f64 / total as f64 };
    85→        (hits, misses, rate)
    86→    }
    87→
    88→    pub fn clear(&mut self) {
    89→        self.tokens.clear();
    90→    }
    91→
    92→    pub fn len(&self) -> usize {
    93→        self.tokens.len()
    94→    }
    95→
    96→    pub fn is_empty(&self) -> bool {
    97→        self.tokens.is_empty()
    98→    }
    99→}
