   101→/// Variable: Represents a defined variable in compilation
   102→#[derive(Debug, Clone)]
   103→pub struct Variable {
   104→    pub name: String,
   105→    pub var_type: String,
   106→    pub scope: u32,
   107→    pub value: Option<String>,
   108→}
   109→
   110→/// Function: Represents a defined function in compilation
   111→#[derive(Debug, Clone)]
   112→pub struct Function {
   113→    pub name: String,
   114→    pub params: Vec<(String, String)>, // (name, type)
   115→    pub return_type: String,
   116→    pub scope: u32,
   117→}
